import { Mesh, PlaneGeometry, Group, SpriteMaterial, Sprite } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNodeFn, uv as uvNode, uniform, vec2, mix, vec4 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-collection-card-2';

  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Atlas region: x, y, w, h
  const region = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h; // 1.6
  const planeW = 2.0;
  const planeH = planeW / aspect;

  const geo = new THREE.PlaneGeometry(planeW, planeH, 1, 1);

  // MeshBasicNodeMaterial with .map node (TSL)
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    toneMapped: false,
  });

  const plane = new THREE.Mesh(geo, mat);
  plane.renderOrder = 2;
  group.add(plane);

  // Backdrop plane for staging (subtle dark surface so the card isn't floating in void)
  const backdropGeo = new THREE.PlaneGeometry(planeW + 0.5, planeH + 0.5, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.85,
    toneMapped: false,
  });
  // Engineered gradient via TSL nodes: vertical ink->surface
  const gradUv = uvNode();
  const t = gradUv.y;
  const colA = new THREE.Color(colors.surface);
  const colB = new THREE.Color(colors.ink);
  const gradColor = mix(vec4(colA.r, colA.g, colA.b, 1.0), vec4(colB.r, colB.g, colB.b, 1.0), t);
  backdropMat.colorNode = gradColor;
  backdropMat.opacityNode = uniform(0.85);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.05;
  backdrop.renderOrder = 1;
  group.add(backdrop);

  // Subtle accent edge (thin rim line on the right) — accent on <=10% of frame
  const edgeGeo = new THREE.PlaneGeometry(0.04, planeH, 1, 1);
  const edgeMat = new MeshBasicNodeMaterial({ toneMapped: false, transparent: true, opacity: 0.9 });
  const accentCol = new THREE.Color(colors.accent);
  edgeMat.colorNode = vec4(accentCol.r, accentCol.g, accentCol.b, 1.0);
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.set(planeW * 0.5 + 0.02, 0, 0.02);
  edge.renderOrder = 3;
  group.add(edge);

  // Load the ceramic-grain texture and wire UV atlas offsets
  let tex = null;
  let pendingRepeat = null;
  let texUniform = uniform(null);

  ctx.textureLoader.loadTexture(imageUrl).then((loadedTex) => {
    tex = loadedTex;
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.generateMipmaps = false;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;

    // Compute atlas UV offset/repeat from region vs full texture dims
    const fullW = tex.image?.width ?? region.w;
    const fullH = tex.image?.height ?? region.h;
    const repeatX = region.w / fullW;
    const repeatY = region.h / fullH;
    const offsetX = region.x / fullW;
    // Flip Y for three's UV origin (bottom-left) vs image origin (top-left)
    const offsetY = 1.0 - (region.y / fullH) - repeatY;

    tex.offset.set(offsetX, offsetY);
    tex.repeat.set(repeatX, repeatY);

    texUniform.value = tex;
    // Bind texture node to color
    const texNode = textureNodeFn(tex, uvNode());
    mat.map = tex;
    mat.colorNode = mix(
      vec4(0.0, 0.0, 0.0, 1.0),
      texNode,
      1.0
    );
    mat.needsUpdate = true;
  }).catch((e) => {
    // Fallback: engineered gradient surface
    const fbUv = uvNode();
    const fb = mix(
      vec4(new THREE.Color(colors.surface).r, new THREE.Color(colors.surface).g, new THREE.Color(colors.surface).b, 1.0),
      vec4(new THREE.Color(colors.ink).r, new THREE.Color(colors.ink).g, new THREE.Color(colors.ink).b, 1.0),
      fbUv.y
    );
    mat.colorNode = fb;
    mat.needsUpdate = true;
  });

  // Initial color node placeholder (gradient) until texture arrives
  const initUv = uvNode();
  mat.colorNode = mix(
    vec4(new THREE.Color(colors.surface).r, new THREE.Color(colors.surface).g, new THREE.Color(colors.surface).b, 1.0),
    vec4(new THREE.Color(colors.ink).r, new THREE.Color(colors.ink).g, new THREE.Color(colors.ink).b, 1.0),
    initUv.y
  );
  mat.opacityNode = uniform(1.0);

  // Billboard: face camera each frame via onBeforeRender (no DOM events)
  plane.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  // Entrance: weighted-settle (overshoot 1.04 -> 1.0)
  const tl = gsap.timeline();
  group.scale.setScalar(0.001);
  tl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.7, ease: 'power3.out' });
  tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
  tl.fromTo(group.position, { y: 0.4 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);

  // Subtle grain drift idle motion (breathing <=2%)
  const idle = gsap.to(plane.position, {
    z: 0.04,
    duration: 3.6,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
  });

  // Cleanup
  const primHandles = [];
  group.userData.cleanup = () => {
    tl.kill();
    idle.kill();
    for (const h of primHandles) { try { h.cleanup?.(); } catch (_) {} }
    geo.dispose();
    backdropGeo.dispose();
    edgeGeo.dispose();
    mat.dispose();
    backdropMat.dispose();
    edgeMat.dispose();
    if (tex) tex.dispose();
  };

  group.userData.handlers = {};

  return group;
}
